import{_ as l,r as t,o as c,c as i,e,a,d as s,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Блоки содержимого - October CMS - 3.x","titleTemplate":false,"description":"Выделенные файлы для хранения и обновления содержимого страниц.","frontmatter":{"subtitle":"Выделенные файлы для хранения и обновления содержимого страниц."},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Рендеринг блоков содержимого","slug":"рендеринг-блоков-содержимого","link":"#рендеринг-блоков-содержимого","children":[]},{"level":2,"title":"Передача переменных в блоки содержимого","slug":"передача-переменных-в-блоки-содержимого","link":"#передача-переменных-в-блоки-содержимого","children":[{"level":3,"title":"Глобальные переменные","slug":"глобальные-переменные","link":"#глобальные-переменные","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}]}],"relativePath":"3.x/ru/cms/themes/content.md","filePath":"3.x/ru/cms/themes/content.md"}'),d={name:"3.x/ru/cms/themes/content.md"};function u(g,n,k,h,m,v){const o=t("pre-heading"),p=t("post-heading");return c(),i("div",null,[e(o),n[0]||(n[0]=a("h1",null,"Блоки содержимого",-1)),e(p),n[1]||(n[1]=a("p",null,[s("Блоки содержимого могут быть текстовыми, HTML или "),a("a",{href:"http://daringfireball.net/projects/markdown/syntax",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Markdown"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),a("span",{class:"sr-only"},"(opens new window)")])]),s(" блоками, которые редактируются отдельно от страницы или макета. Они предназначены для хранения только статического содержимого и поддерживают базовые шаблонные переменные. "),a("a",{href:"./partials.html"},"Фрагменты"),s(" более гибки и должны использоваться для генерации динамического содержимого.")],-1)),n[2]||(n[2]=r(`<h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Файлы блоков содержимого располагаются в подкаталоге <strong>/content</strong> каталога темы. Для файлов содержимого поддерживаются следующие расширения.</p><div class="table"><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><strong>html</strong></td><td>Используется для HTML-разметки (WYSIWYG-редактор).</td></tr><tr><td><strong>htm</strong></td><td>Используется для HTML-разметки (редактор кода).</td></tr><tr><td><strong>txt</strong></td><td>Используется для обычного текста.</td></tr><tr><td><strong>md</strong></td><td>Используется для синтаксиса Markdown.</td></tr></tbody></table></div><p>Расширение влияет на режим отображения блока содержимого в интерфейсе администрирования — WYSIWYG-редактор, редактор кода или редактор Markdown. Оно также определяет способ рендеринга блоков на сайте; например, блоки Markdown будут преобразованы в HTML перед отображением.</p><h2 id="рендеринг-блоков-содержимого"><a href="#рендеринг-блоков-содержимого" class="header-anchor">#</a> Рендеринг блоков содержимого</h2><p>Используйте тег <code>{% content &#39;file.htm&#39; %}</code> для рендеринга блока содержимого на <a href="./pages.html">странице</a>, во <a href="./partials.html">фрагменте</a> или в <a href="./layouts.html">макете</a>.</p><p>Этот пример показывает полную страницу с рендерингом блока содержимого.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/contacts</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contacts<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>contacts.html<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Ещё один пример рендеринга Markdown с расширением <code>md</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>my-markdown.md<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="передача-переменных-в-блоки-содержимого"><a href="#передача-переменных-в-блоки-содержимого" class="header-anchor">#</a> Передача переменных в блоки содержимого</h2><p>Иногда может потребоваться передать переменные в блок содержимого из внешнего кода. Хотя блоки содержимого не поддерживают разметку Twig, они поддерживают использование переменных с базовым синтаксисом. Вы можете передавать переменные в блоки содержимого, указывая их после имени блока содержимого в теге <code>{% content %}</code>.</p><p>Передача переменной с именем <code>name</code> и значением <strong>John</strong> в блок содержимого.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span> name<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>John<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Внутри блока содержимого переменные доступны с использованием одинарных <em>фигурных скобок</em>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>This is a demo for {name}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>Более подробную информацию об использовании переменных можно найти в <a href="./../../markup/tag/content.html">руководстве по разметке</a>.</p></div><h3 id="глобальные-переменные"><a href="#глобальные-переменные" class="header-anchor">#</a> Глобальные переменные</h3><p>Вы можете зарегистрировать переменные, глобально доступные для всех блоков содержимого, с помощью метода <code>View::share</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Обычно этот метод размещается внутри метода register или boot <a href="./../../extend/system/plugins.html">файла регистрации плагина</a>. Используя приведённый выше пример, переменная <code>{site_name}</code> будет доступна внутри всех блоков содержимого.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Welcome to {site_name}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/content.html">Content Twig Tag</a></li></ul></div>`,24))])}const x=l(d,[["render",u]]);export{f as __pageData,x as default};
